import { describe, expect, test } from "bun:test";
import * as THREE from "three";
import { CUSTOM_NAME_MAX_LEN, ENCHANT_MAX_LEVEL, INVENTORY_SLOTS } from "@/lib/game/config";
import { MAX_HEARTS, MAX_HUNGER } from "@/lib/game/config";
import {
  inventorySlotsSnapshot,
  migrateSaveV1toV2,
  migrateSaveV2toV3,
  migrateSaveV3toV4,
  migrateSaveV4toV5,
  migrateSaveV5toV6,
  migrateSaveV6toV7,
  migrateSaveV7toV8,
  migrateSaveV8toV9,
  migrateSaveV9toV10,
  migrateSaveV10toV11,
  migrateSaveV11toV12,
  migrateSaveV12toV13,
  migrateSaveV13toV14,
  migrateSaveV14toV15,
  migrateSaveV15toV16,
  migrateSaveV16toV17,
  isPersistentMob,
  readContainers,
  readLootedChests,
  readSave,
  restoreMobs,
  serializeMobs,
  restoreDayClock,
  restoreEquippedArmor,
  restoreDifficulty,
